# --- --strict-types：FHIR R4 已知字段类型收紧 -------------------------------

# Observation.value[x] 的成员名（与成员顺序对应 Quantity/Integer/String/Boolean）。
# quantity 为对象（Quantity）、integer 为整数（bool 在 Python 中是 int 子类需
# 显式排除）、string 为字符串（不接受数字代字符串）、boolean 为布尔。
OBSERVATION_VALUE_FIELDS = tuple(
    "value" + cap for cap in ("Quantity", "Integer", "String", "Boolean")
)


def _type_label(value):
    """JSON 类型标签，用于错误消息（bool 与 int 区分）。"""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, str):
        return "string"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    return type(value).__name__


def _expect_type(value, expected, label):
    """按 FHIR 原语期望的 JSON 类型校验；expected 取 object/array/string/
    integer/boolean。null、形状错误、数字代字符串一律拒绝。"""
    if expected == "object":
        ok = isinstance(value, dict)
        expected_text = "对象"
    elif expected == "array":
        ok = isinstance(value, list)
        expected_text = "数组"
    elif expected == "string":
        ok = isinstance(value, str)
        expected_text = "字符串"
    elif expected == "integer":
        ok = isinstance(value, int) and not isinstance(value, bool)
        expected_text = "整数"
    elif expected == "boolean":
        ok = isinstance(value, bool)
        expected_text = "布尔"
    else:  # pragma: no cover - 仅内部使用
        raise ValueError("unknown expected type %r" % expected)
    if not ok:
        raise FhirValidationError(
            "%s 必须为%s，实际为 %s" % (label, expected_text, _type_label(value))
        )


