def _strict_codeable_concept(concept, label):
    """CodeableConcept：coding 为对象数组，元素 system/code/display 为字符串、
    userSelected 为布尔；text 若出现必须为字符串。未知字段原样保留。"""
    _expect_type(concept, "object", label)
    if "coding" in concept:
        codings = concept["coding"]
        _expect_type(codings, "array", label + ".coding")
        for pos, coding in enumerate(codings):
            coding_label = "%s.coding[%d]" % (label, pos)
            _expect_type(coding, "object", coding_label)
            for field in ("system", "code", "display"):
                if field in coding:
                    _expect_type(coding[field], "string", "%s.%s" % (coding_label, field))
            if "userSelected" in coding:
                _expect_type(
                    coding["userSelected"], "boolean", coding_label + ".userSelected"
                )
    if "text" in concept:
        _expect_type(concept["text"], "string", label + ".text")


def _strict_object_array(items, label):
    """HumanName / ContactPoint：必须为对象数组（元素内部字段不收紧）。"""
    _expect_type(items, "array", label)
    for pos, item in enumerate(items):
        _expect_type(item, "object", "%s[%d]" % (label, pos))


def _strict_patient(resource, prefix):
    if "active" in resource:
        _expect_type(resource["active"], "boolean", prefix + ".active")
    if "gender" in resource:
        gender = resource["gender"]
        if gender not in ("male", "female", "other", "unknown"):
            raise FhirValidationError(
                "%s.gender 仅限 male/female/other/unknown，实际为 %s"
                % (prefix, json.dumps(gender, ensure_ascii=False))
            )
    if "birthDate" in resource:
        _expect_type(resource["birthDate"], "string", prefix + ".birthDate")
        _parse_date(resource["birthDate"], prefix + ".birthDate")
    for field in ("name", "telecom"):
        if field in resource:
            _strict_object_array(resource[field], "%s.%s" % (prefix, field))


def _strict_observation(resource, prefix):
    if "code" in resource:
        _strict_codeable_concept(resource["code"], prefix + ".code")
    if "valueCodeableConcept" in resource:
        _strict_codeable_concept(
            resource["valueCodeableConcept"], prefix + ".valueCodeableConcept"
        )

    # value[x] 至多一个；多个成员同时出现直接拒绝。
    present = [f for f in OBSERVATION_VALUE_FIELDS if f in resource]
    if len(present) > 1:
        raise FhirValidationError(
            "%s 的 value[x] 至多出现一个，实际同时出现 %s"
            % (prefix, "、".join(present))
        )
    if "valueQuantity" in resource:
        _expect_type(resource["valueQuantity"], "object", prefix + ".valueQuantity")
    if "valueInteger" in resource:
        _expect_type(resource["valueInteger"], "integer", prefix + ".valueInteger")
    if "valueString" in resource:
        _expect_type(resource["valueString"], "string", prefix + ".valueString")
    if "valueBoolean" in resource:
        _expect_type(resource["valueBoolean"], "boolean", prefix + ".valueBoolean")

    if "effectiveDateTime" in resource:
        _expect_type(resource["effectiveDateTime"], "string", prefix + ".effectiveDateTime")
        _parse_date_time(resource["effectiveDateTime"], prefix + ".effectiveDateTime")
    if "issued" in resource:
        _expect_type(resource["issued"], "string", prefix + ".issued")
        _parse_date_time(resource["issued"], prefix + ".issued")


def _strict_condition(resource, prefix):
    for field in ("clinicalStatus", "verificationStatus", "code"):
        if field in resource:
            _strict_codeable_concept(resource[field], "%s.%s" % (prefix, field))
    if "onsetDateTime" in resource:
        _expect_type(resource["onsetDateTime"], "string", prefix + ".onsetDateTime")
        _parse_date_time(resource["onsetDateTime"], prefix + ".onsetDateTime")
    if "recordedDate" in resource:
        _expect_type(resource["recordedDate"], "string", prefix + ".recordedDate")
        _parse_date(resource["recordedDate"], prefix + ".recordedDate")


def strict_validate_resource(resource, prefix=None):
    """--strict-types 下对已知字段做 FHIR R4 类型收紧；未知字段保留不检查。

    调用方需先通过 validate_resource 的基线校验（resourceType 与 id）。
    prefix 为批量 entry 中的位置前缀（如 Bundle.entry[0].resource）。
    """
    resource_type = resource.get("resourceType")
    label = prefix or resource_type
    if resource_type == "Patient":
        _strict_patient(resource, label)
    elif resource_type == "Observation":
        _strict_observation(resource, label)
    elif resource_type == "Condition":
        _strict_condition(resource, label)


def validate_resource(resource, strict=False, prefix=None):
    """按任务约定校验 Patient / Observation / Condition。"""
    if not isinstance(resource, dict):
        raise FhirValidationError("resource 必须为对象")

    resource_type = resource.get("resourceType")
    if resource_type not in ALLOWED_RESOURCE_TYPES:
        raise FhirValidationError(
            "resource.resourceType 仅限 %s" % "、".join(ALLOWED_RESOURCE_TYPES)
        )

    if not _is_nonempty_str(resource.get("id")):
        raise FhirValidationError("resource.id 必须为非空字符串")

    if resource_type == "Observation":
        if resource.get("status") not in OBSERVATION_STATUSES:
